class Solution:
    def longestPalindrome(self, s: str) -> str:
        bs, bl = 0, 1; n = len(s)
        for c in range(2 * n - 1):
            l, r = c // 2, c // 2 + c % 2
            while l >= 0 and r < n and s[l] == s[r]: l -= 1; r += 1
            L = r - l - 1
            if L > bl or (L == bl and l + 1 < bs): bs, bl = l + 1, L
        return s[bs:bs + bl]

