function longestPalindrome(s) {
  const n = s.length; const dp = Array.from({length: n}, () => new Uint8Array(n));
  let bs = 0, bl = 1;
  for (let len = 1; len <= n; len++) for (let i = 0; i + len <= n; i++) {
    const j = i + len - 1;
    if (s[i] === s[j] && (len <= 2 || dp[i + 1][j - 1])) { dp[i][j] = 1; if (len > bl) { bl = len; bs = i; } }
  }
  return s.slice(bs, bs + bl);
}
